select m.id,v.k,v.t,v.ft,v.r,v.s,v.o::jsonb from platform_modules m cross join (values
('page-code','کد صفحه','text',true,10,'{}'),('page-title','عنوان صفحه','text',true,20,'{}'),('page-key','کلید صفحه','text',true,30,'{}'),('route','مسیر صفحه','text',true,40,'{}'),('page-type','نوع صفحه','select',true,50,'{"options":["داخلی","فرود","داشبورد","اطلاعاتی","سازمانی","سایر"]}'),('template','قالب پایه','text',false,60,'{}'),('version','نسخه','number',true,70,'{}'),('definition-reference','مرجع تعریف صفحه','text',false,80,'{}'),('visibility','سطح نمایش','select',true,90,'{"options":["عمومی","کاربران واردشده","نقش‌محور","سازمانی"]}'),('status','وضعیت','select',true,100,'{"options":["پیش‌نویس","فعال","غیرفعال","آرشیو شده"]}'),('published-at','تاریخ انتشار','datetime',false,110,'{}'),('owner','مالک صفحه','text',false,120,'{}'),('seo-title','عنوان SEO','text',false,130,'{}'),('seo-description','توضیحات SEO','textarea',false,140,'{}'),('notes','یادداشت','textarea',false,150,'{}')
) v(k,t,ft,r,s,o) where m.code='34-page-builder' on conflict(module_id,field_key) do update set title=excluded.title,field_type=excluded.field_type,required=excluded.required,sort_order=excluded.sort_order,options=excluded.options;
