insert into platform_modules(code,title,is_active) values ('34-page-builder','صفحه‌ساز و مدیریت صفحات',true) on conflict(code) do update set title=excluded.title,is_active=true;
insert into module_field_definitions(module_id,field_key,title,field_type,required,sort_order,options)
insert into module_actions(module_id,action_code,title,permission) select m.id,v.a,v.t,v.p from platform_modules m cross join (values
('read','مشاهده صفحات','modules:34-page-builder:read'),('write','ساخت و ویرایش صفحه','modules:34-page-builder:write'),('delete','حذف صفحه','modules:34-page-builder:delete'),('publish','انتشار صفحه','modules:34-page-builder:publish'),('disable','غیرفعال‌سازی صفحه','modules:34-page-builder:disable'),('duplicate','تکثیر صفحه','modules:34-page-builder:duplicate'),('version','مدیریت نسخه','modules:34-page-builder:version')) v(a,t,p) where m.code='34-page-builder' on conflict(module_id,action_code) do update set title=excluded.title,permission=excluded.permission;